import { expect, test, uniqueName } from "../../fixtures";

test("Fields that cannot be parsed get low confidence", { tag: "@DOC-03" }, async ({ apiAs }) => {
  // Arrange: a member signs in and creates a draft vendor
  const member = await apiAs("member");
  const vendorRes = await member.post("/api/vendors", {
    data: {
      name: uniqueName("DOC-03 Vendor"),
      category: "services",
      contact_email: `doc03-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
    },
  });
  expect(vendorRes.status(), await vendorRes.text()).toBe(201);
  const vendor = await vendorRes.json();
  expect(vendor.status, await vendorRes.text()).toBe("draft");

  // Act: upload an insurance certificate whose expiry date cannot be parsed
  const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "insurance_certificate",
      file: {
        name: "certificate.txt",
        mimeType: "text/plain",
        buffer: Buffer.from("Insurance certificate\nExpiry date: next spring\n"),
      },
    },
  });
  expect(uploadRes.status(), await uploadRes.text()).toBe(201);
  const document = await uploadRes.json();

  // Assert: processing finishes in the background
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/documents/${document.id}`);
        return (await res.json()).status;
      },
      { timeout: 60_000, message: "document processing should finish" },
    )
    .not.toBe("processing");

  const finalDocRes = await member.get(`/api/documents/${document.id}`);
  expect(finalDocRes.status(), await finalDocRes.text()).toBe(200);
  const finalDoc = await finalDocRes.json();
  expect(finalDoc.status, JSON.stringify(finalDoc)).toBe("extracted");

  const extractionRes = await member.get(`/api/documents/${document.id}/extraction`);
  expect(extractionRes.status(), await extractionRes.text()).toBe(200);
  const extraction = await extractionRes.json();

  const expiry = extraction.fields?.expiry_date;
  expect(expiry, JSON.stringify(extraction.fields)).toBeDefined();
  expect(expiry.value, JSON.stringify(extraction.fields)).toBeNull();
  expect(expiry.confidence, JSON.stringify(extraction.fields)).toBeLessThan(0.5);
});
